  const { dir } = repo()
  rmSync(join(dir, '.claude/trace.json'))
  const out = hook({ tool_name: 'Edit', tool_input: { file_path: join(dir, 'a.md') }, cwd: dir }, failingGit('*":.claude/trace.json "*', 'exec sleep 10'))
  assert.equal(out?.permissionDecision, 'deny')
