})

test('a git that fails without saying no, about the marker or the default branch, refuses edits, commits and PRs', () => {
  const unreadable = 'echo "fatal: detected dubious ownership in repository" >&2; exit 128'
  // A branch that committed the marker's deletion: only the default branch still has it.
  const deleted = () => {
    const { dir, git } = repo()
    git('checkout', '-qb', 'topic')
    git('rm', '-q', '.claude/trace.json')
    git('commit', '-qm', 'drop the marker')
    return dir
  }
  const asIs = deleted()
  const edit = () => String(hook({ tool_name: 'Edit', tool_input: { file_path: join(asIs, 'a.md') }, cwd: asIs })?.permissionDecisionReason)
  assert.match(edit(), /names no issue/, 'while git answers, the default branch has the marker')
  execFileSync('git', ['-C', asIs, 'tag', 'main'])
  assert.match(edit(), /names no issue/, 'a tag named for the default branch does not stand in for it')
  for (const [when, fails] of [
    ['*" HEAD:.claude/trace.json "*', unreadable],
    ['*" HEAD:.claude/trace.json "*', 'kill -9 $$'],
    ['*" refs/remotes/origin/HEAD "*', unreadable],
    ['*" show-ref "*', unreadable],
    ['*" refs/heads/main:.claude/trace.json "*', unreadable],
  ]) {
    const dir = deleted()
    for (const [tool, input] of /** @type {[string, Record<string, string>][]} */ ([
      ['Edit', { file_path: join(dir, 'a.md') }],
      ['Bash', { command: 'git commit -m "x #6"' }],
      ['Bash', { command: 'gh pr create -t t -b "Closes #6"' }],
    ])) {
      const out = hook({ tool_name: tool, tool_input: input, cwd: dir }, failingGit(when, fails))
      assert.equal(out?.permissionDecision, 'deny', `${fails} on ${when}: ${tool} ${JSON.stringify(input)}`)
      assert.match(out.permissionDecisionReason, /could not be checked.*TRACE_BYPASS=1/)
    }
  }
})

