/** A git repository on `main`, opted in to the trace unless `marked` is false. */
function repo(marked = true) {
  const dir = realpathSync(mkdtempSync(join(tmpdir(), 'trace-')))
  const git = (/** @type {string[]} */ ...args) =>
    execFileSync('git', ['-c', 'user.name=t', '-c', 'user.email=t@t', '-c', 'commit.gpgsign=false', ...args], { cwd: dir, stdio: 'ignore' })
  git('init', '-q', '-b', 'main')
  writeFileSync(join(dir, 'a.md'), 'x\n')
  if (marked) {
    mkdirSync(join(dir, '.claude'))
  assert.match(String(archiveBlock('Bash', { command: 'git log -p -1' }, repo, world.timeLeft)), /could not be checked: the hook call ran out of time/)
  assert.throws(() => world.git.message(repo, 'HEAD'), /out of time asking git and GitHub/)
})

test('a history command whose git never answers is denied as unchecked, not as touching the archive', () => {
  const bin = mkdtempSync(join(tmpdir(), 'git-'))
  writeFileSync(join(bin, 'git'), '#!/bin/sh\nkill -9 $$\n', { mode: 0o755 })
  const path = process.env.PATH
  process.env.PATH = `${bin}:${path}`
  try {
    const why = String(bash('git log -p -1'))
    assert.match(why, /could not be checked: git log was stopped by SIGKILL/)
    assert.doesNotMatch(why, /would print changes in the archive/)
    process.env.PATH = '/nonexistent'
    assert.match(String(bash('git log -p -1')), /could not be checked: git log could not be asked \(ENOENT\)/)
  } finally {
    process.env.PATH = path
  }
})

